function validate([rectangles]) {
  if (!Array.isArray(rectangles) || rectangles.length < 1 || rectangles.length > 1000) return 'rectangles needs 1 to 1000 entries.';
  for (const r of rectangles) {
    if (!Array.isArray(r) || r.length !== 2) return 'Each rectangle is a pair [length, width].';
    if (r.some(v => !Number.isInteger(v) || v < 1 || v > 1e9)) return 'Each side is a whole number from 1 to 10^9.';
    if (r[0] === r[1]) return 'A rectangle\'s length and width differ.';
  }
  return null;
}

