function countGoodRectangles(rectangles) {
  const sides = rectangles.map(r => (r[0] < r[1] ? r[0] : r[1]));
  const best = sides.reduce((a, b) => (a > b ? a : b));
  return sides.filter(s => s === best).length;
}

