function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 1000 : 1 + Math.floor(rand() * 8);
  // A small pool of short sides makes ties for the largest square common.
  const pool = Array.from({ length: large ? 6 : 3 }, () => 1 + Math.floor(rand() * (large ? 999999000 : 6)));
  const rectangles = [];
  for (let i = 0; i < n; i++) {
    const short = rand() < 0.6 ? pool[Math.floor(rand() * pool.length)] : 1 + Math.floor(rand() * (large ? 999999000 : 6));
    const long = short + 1 + Math.floor(rand() * (large ? 999 : 4));
    rectangles.push(rand() < 0.5 ? [short, long] : [long, short]);
  }
  return [rectangles];
}
